from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _round(numerator, mode):
    if mode == "half_up":
        return (numerator + 5000) // 10000
    return numerator // 10000


def _ledger(data, priority, tax_base):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if priority == "sequence":
            rank = (sequence, event.get("revision", 0), position)
        else:
            rank = (event.get("revision", 0), position)
        if event_id not in winners or rank > winners[event_id][0]:
            winners[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = raw if tax_base == "original" else net
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _build_ledger(priority, tax_base):
    return lambda data: _ledger(data, priority, tax_base)


SOLVERS = {
    "component_01": _build_ledger("sequence", "original"),
    "component_02": _build_ledger("revision", "discounted"),
    "component_03": _build_ledger("sequence", "discounted"),
    "component_04": _build_ledger("revision", "original"),
    "component_05": _build_ledger("sequence", "original"),
}


def _component_06(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    choices = []
    for name in names:
        versions = sorted({row["version"] for row in packages[name]})
        choices.append([-1] + versions)

    best_vector = None
    best_install = None
    for vector in product(*choices):
        installed = {name: version for name, version in zip(names, vector)
                     if version != -1}
        valid = True
        for name, (low, high) in roots.items():
            if name not in installed or not low <= installed[name] <= high:
                valid = False
                break
        if not valid:
            continue
        for name, version in installed.items():
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                valid = False
                break
        if not valid:
            continue

        graph = {name: [] for name in installed}
        closure = set(roots)
        for name, version in installed.items():
            row = next((r for r in packages[name] if r["version"] == version), None)
            if row is None:
                valid = False
                break
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in installed or not dep["min"] <= installed[target] <= dep["max"]:
                    valid = False
                    break
                graph[name].append(target)
                closure.add(target)
            if not valid:
                break
        if not valid or closure != set(installed):
            continue

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_install = installed

    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


SOLVERS["component_06"] = _component_06


def _component_07(data):
    from itertools import combinations
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        selected = tuple(sorted(ids))
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and selected > best_ids)):
            best_value, best_ids = value, selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


SOLVERS["component_07"] = _component_07


def _component_08(data):
    import heapq

    required = data.get("required", [])
    bit_for = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    start_state = (source, data["coupons"], initial_mask)
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, data["coupons"], initial_mask)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_remaining, next_mask)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_remaining, next_mask))
    return {"arrival": None}


SOLVERS["component_08"] = _component_08
